1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The single duplicate check for {@code POST /api/owners}: rejects the request only when the new
11	 * owner's whole {@code identityKey} equals an existing owner's identityKey (see {@link OwnerIdentity}).
12	 * This subsumes the former separate telephone, email and household checks — because the telephone is
13	 * part of the key, two members of the same household with different telephones are both allowed; only
14	 * an exact full-key match is a duplicate. On a match it throws {@link DuplicateIdentityException},
15	 * handled globally as 409.
16	 */
17	public class EnsureIdentityUnique {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateIdentityException {
21	        String lastName = OwnerIdentity.normalizeName(request.getLastName());
22	        String address = OwnerAddress.normalize(request.getAddress());
23	
24	        // The household the new owner would join: any existing owner sharing the normalized lastName
25	        // and address. When present, both this owner and those peers carry the same derived household
26	        // id; when absent, the household component is empty (a solo owner).
27	        boolean hasPeer = false;
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (sharesHousehold(lastName, address, existing)) {
30	                hasPeer = true;
31	                break;
32	            }
33	        }
34	        String newHousehold = hasPeer ? OwnerIdentity.deriveHouseholdId(lastName, address) : "";
35	        String newKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), newHousehold);
36	
37	        for (Owner existing : ownerRepository.findAll()) {
38	            // A household peer shares the new owner's derived id even if it predates the household and
39	            // has not been back-filled yet; any other owner is compared on its own stored household.
40	            String household = sharesHousehold(lastName, address, existing)
41	                    ? newHousehold
42	                    : (existing.getHouseholdId() == null ? "" : existing.getHouseholdId());
43	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(), household);
44	            if (newKey.equals(existingKey)) {
45	                throw new DuplicateIdentityException(newKey);
46	            }
47	        }
48	    }
49	
50	    private static boolean sharesHousehold(String lastName, String address, Owner existing) {
51	        return lastName.equals(OwnerIdentity.normalizeName(existing.getLastName()))
52	                && address.equals(OwnerAddress.normalize(existing.getAddress()));
53	    }
54	}
