1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
10	
11	/**
12	 * Rejects a create-owner request once the maximum number of owners
13	 * ({@link DailyOwnerLimitException#LIMIT}) have already been created on the same business day,
14	 * counted by {@link Owner#getRegistrationDate()}. The day counted is this request's <em>adjusted</em>
15	 * business day: the effective registration date — supplied in the request or defaulted to the server
16	 * date — rolled forward off a weekend to the next Monday, matching what {@link BuildOwner} will store.
17	 * Runs before {@link SaveOwner}, so the new owner is not yet counted; a business day already holding
18	 * 100 owners causes the 101st request to fail with 429.
19	 */
20	public class EnsureDailyOwnerLimit {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DailyOwnerLimitException {
24	        LocalDate effective = request.getRegistrationDate();
25	        if (effective == null) {
26	            effective = LocalDate.now();
27	        }
28	        LocalDate businessDay = BusinessDays.rollForward(effective);
29	        int count = 0;
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (businessDay.equals(existing.getRegistrationDate())) {
32	                count++;
33	            }
34	        }
35	        if (count >= DailyOwnerLimitException.LIMIT) {
36	            throw new DailyOwnerLimitException(businessDay, count);
37	        }
38	    }
39	}
