1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Runs after {@link EnsureHouseholdUnique} has allowed the request: when the new owner shares a
12	 * household with one or more existing owners (same lastName and address, compared the same way as
13	 * {@link EnsureHouseholdUnique}), it assigns them all the same {@code householdId} — a stable
14	 * identifier derived deterministically from the normalized lastName and address, so every member of
15	 * the household resolves to the same value regardless of creation order. Existing members that
16	 * predate the household are back-filled so both sides carry the shared id. An owner with no household
17	 * peer keeps a null {@code householdId}. It also records {@code householdSize} — the number of owners
18	 * that share the household after this create (the existing peers plus this new owner).
19	 */
20	public class AssignHouseholdId {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String lastName = normalize(owner.getLastName());
24	        String address = OwnerAddress.normalize(owner.getAddress());
25	        List<Owner> household = new ArrayList<>();
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (lastName.equals(normalize(existing.getLastName()))
28	                    && address.equals(OwnerAddress.normalize(existing.getAddress()))) {
29	                household.add(existing);
30	            }
31	        }
32	        // Record the household size after this create: the existing peers plus this new owner.
33	        owner.setHouseholdSize(household.size() + 1);
34	        if (household.isEmpty()) {
35	            return; // no peer at this lastName + address, so no shared household
36	        }
37	        String householdId = OwnerIdentity.deriveHouseholdId(lastName, address);
38	        owner.setHouseholdId(householdId);
39	        for (Owner existing : household) {
40	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
41	                existing.setHouseholdId(householdId);
42	                ownerRepository.save(existing);
43	            }
44	        }
45	    }
46	
47	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
48	    private static String normalize(String value) {
49	        return OwnerIdentity.normalizeName(value);
50	    }
51	}
