5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many existing owners already shared the new owner's name at the moment it was created.
9	 * Runs before {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns only the owners that
10	 * predate this create. It counts those whose firstName and lastName both match the new owner's,
11	 * compared case-insensitively, and stores the total as {@code namesakeCount}; a unique name yields 0.
12	 */
13	public class CountNamesakes {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        int count = 0;
17	        for (Owner existing : ownerRepository.findAll()) {
18	            if (equalsIgnoreCase(owner.getFirstName(), existing.getFirstName())
19	                    && equalsIgnoreCase(owner.getLastName(), existing.getLastName())) {
20	                count++;
21	            }
22	        }
23	        owner.setNamesakeCount(count);
24	    }
25	
26	    private static boolean equalsIgnoreCase(String a, String b) {
27	        return a == null ? b == null : a.equalsIgnoreCase(b);
28	    }
29	}
