7	/**
8	 * Flags a create-owner request as a bulk sign-up. Runs before {@link SaveOwner}, so
9	 * {@link OwnerRepository#findAll()} returns only the owners that predate this create. It counts
10	 * those already registered on this owner's (adjusted) business day — the date {@link BuildOwner}
11	 * stored on the entity — and sets {@code bulkSignupWarning} true when more than
12	 * {@link #BULK_SIGNUP_THRESHOLD} such owners already exist; otherwise false. The count mirrors the
13	 * per-day accumulation used by {@link EnsureDailyOwnerLimit}.
14	 */
15	public class FlagBulkSignup {
16	
17	    /** More than this many owners already created on the business day marks a bulk sign-up. */
18	    public static final int BULK_SIGNUP_THRESHOLD = 80;
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        int count = 0;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (owner.getRegistrationDate().equals(existing.getRegistrationDate())) {
24	                count++;
25	            }
26	        }
27	        owner.setBulkSignupWarning(count > BULK_SIGNUP_THRESHOLD);
28	    }
29	}
