1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * The registration date must fall on a business day. A date landing on a Saturday or Sunday rolls
8	 * forward to the following Monday; a weekday is left unchanged. Applied to the effective registration
9	 * date — whether supplied in the request or defaulted to the server date — so every value derived
10	 * from the registration date (membership number year, per-day create limit) sees the adjusted date.
11	 */
12	final class BusinessDays {
13	
14	    private BusinessDays() {
15	    }
16	
17	    /** Roll a weekend date forward to the next Monday; return a weekday unchanged. */
18	    static LocalDate rollForward(LocalDate date) {
19	        LocalDate rolled = date;
20	        while (rolled.getDayOfWeek() == DayOfWeek.SATURDAY
21	                || rolled.getDayOfWeek() == DayOfWeek.SUNDAY) {
22	            rolled = rolled.plusDays(1);
23	        }
24	        return rolled;
25	    }
26	}
