1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
8	
9	/**
10	 * The single source of truth for an owner's derived {@code identityKey} and its parts. All duplicate
11	 * detection is now expressed through this one key:
12	 *
13	 * <pre>identityKey = normalizedTelephone + '|' + (email or empty) + '|' + householdId</pre>
14	 *
15	 * <p>Two owners are duplicates only when their <em>whole</em> identityKey is equal. Because the
16	 * telephone is part of the key, two members of the same household (same householdId) with different
17	 * telephones have different identityKeys and are both allowed; only an exact full-key match is a
18	 * duplicate.
19	 *
20	 * <p>The household component is the deterministic id derived from the normalized lastName and address
21	 * (see {@link #deriveHouseholdId}); it is the empty string for an owner with no shared household, so
22	 * two solo owners with the same telephone and email collide.
23	 */
24	public final class OwnerIdentity {
25	
26	    private OwnerIdentity() {
27	    }
28	
29	    /**
30	     * The identityKey from its already-known parts. Telephone is canonicalized to E.164 and email is
31	     * lower-cased so differing formats or case do not hide a match; a null household is the empty
32	     * string.
33	     */
34	    public static String key(String telephone, String email, String householdId) {
35	        return canonicalTelephone(telephone) + '|' + normalizedEmail(email) + '|'
36	                + (householdId == null ? "" : householdId);
37	    }
38	
39	    /**
40	     * The E.164 form used for comparison. A value that is already E.164 is returned unchanged; a value
41	     * that predates E.164 storage is normalized on the fly, falling back to its bare digits if it
42	     * cannot form valid E.164.
43	     */
44	    public static String canonicalTelephone(String value) {
45	        try {
46	            return OwnerTelephone.toE164(value);
47	        }
48	        catch (InvalidTelephoneException ex) {
49	            return value == null ? "" : value.replaceAll("\\D", "");
50	        }
51	    }
52	
53	    /** The email lower-cased and trimmed, or the empty string when null or blank. */
54	    public static String normalizedEmail(String value) {
55	        if (value == null || value.isBlank()) {
56	            return "";
57	        }
58	        return value.trim().toLowerCase();
59	    }
60	
61	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
62	    public static String normalizeName(String value) {
63	        if (value == null) {
64	            return "";
65	        }
66	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
67	    }
68	
69	    /** {@code H-} plus the first 12 upper-case hex chars of SHA-256(lastName + '|' + address). */
70	    public static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
71	        try {
72	            byte[] digest = MessageDigest.getInstance("SHA-256")
73	                    .digest((normalizedLastName + '|' + normalizedAddress).getBytes(StandardCharsets.UTF_8));
74	            StringBuilder sb = new StringBuilder("H-");
75	            for (int i = 0; i < 6; i++) {
76	                sb.append(String.format("%02X", digest[i]));
77	            }
78	            return sb.toString();
79	        }
80	        catch (NoSuchAlgorithmException ex) {
81	            throw new IllegalStateException("SHA-256 not available", ex);
82	        }
83	    }
84	}
