7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
8	
9	/**
10	 * Normalizes an owner {@code telephone} to E.164 form. Spaces, dashes and brackets are stripped; a
11	 * value that already carries a leading {@code '+'} and country code keeps them, otherwise country
12	 * code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
13	 * The result must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'} becomes
14	 * {@code '+61412345678'} and {@code '+64 21 123 456'} becomes {@code '+6421123456'}.
15	 *
16	 * <p>For known country codes the national-number length is also checked: {@code '+61'} requires 9
17	 * national digits and {@code '+1'} requires 10. A number whose national part is the wrong length for
18	 * its country is rejected. Country codes not listed here are only length-checked by the E.164 range.
19	 */
20	final class OwnerTelephone {
21	
22	    /** E.164: a {@code '+'} followed by 8 to 15 digits. */
23	    private static final Pattern E164 = Pattern.compile("\\+[0-9]{8,15}");
24	
25	    /** Formatting characters removed before interpreting the number: spaces, dashes and brackets. */
26	    private static final Pattern FORMATTING = Pattern.compile("[\\s()\\-]");
27	
28	    /**
29	     * Country code (digits after the {@code '+'}) to required national-number length. Ordered
30	     * longest-prefix first so {@code '61'} is matched before the shorter {@code '1'}.
31	     */
32	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
33	    static {
34	        NATIONAL_LENGTHS.put("61", 9);
35	        NATIONAL_LENGTHS.put("1", 10);
36	    }
37	
38	    private OwnerTelephone() {
39	    }
40	
41	    /**
42	     * @return the telephone in E.164 form.
43	     * @throws InvalidTelephoneException when the value cannot form a valid E.164 number.
44	     */
45	    static String toE164(String telephone) throws InvalidTelephoneException {
46	        if (telephone == null) {
47	            throw new InvalidTelephoneException(null);
48	        }
49	        String stripped = FORMATTING.matcher(telephone).replaceAll("");
50	        String e164;
51	        if (stripped.startsWith("+")) {
52	            e164 = stripped;
53	        } else {
54	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
55	            e164 = "+61" + national;
56	        }
57	        if (!E164.matcher(e164).matches()) {
58	            throw new InvalidTelephoneException(telephone);
59	        }
60	        String digits = e164.substring(1);
61	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
62	            if (digits.startsWith(country.getKey())) {
63	                int nationalLength = digits.length() - country.getKey().length();
64	                if (nationalLength != country.getValue()) {
65	                    throw new InvalidTelephoneException(telephone);
66	                }
67	                break;
68	            }
69	        }
70	        return e164;
71	    }
72	}
