3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
7	
8	/**
9	 * Validates the optional owner {@code postcode}. Postcode is absent when null or blank; when present it
10	 * must be a 4-digit value and, when the city maps to a known region, fall within that region's fixed
11	 * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
12	 * postcode. The postcode is stored and returned as given (trimmed).
13	 */
14	final class Postcode {
15	
16	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
17	
18	    /** City -> canonical region, from the fixed city-to-region table. */
19	    private static final Map<String, String> CITY_REGION = Map.of(
20	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
21	
22	    /** Region -> inclusive 4-digit postcode range {low, high}. */
23	    private static final Map<String, int[]> REGION_RANGE = Map.of(
24	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
25	
26	    private Postcode() {
27	    }
28	
29	    /**
30	     * @return the trimmed postcode, or {@code null} when it is absent (null or blank).
31	     * @throws InvalidPostcodeException when present but not a 4-digit value, or out of range for the
32	     *         city's region.
33	     */
34	    static String normalize(String postcode, String city) throws InvalidPostcodeException {
35	        if (postcode == null || postcode.isBlank()) {
36	            return null;
37	        }
38	        String trimmed = postcode.trim();
39	        if (!FOUR_DIGITS.matcher(trimmed).matches()) {
40	            throw new InvalidPostcodeException(postcode);
41	        }
42	        String region = city == null ? null : CITY_REGION.get(city);
43	        if (region != null) {
44	            int[] range = REGION_RANGE.get(region);
45	            int value = Integer.parseInt(trimmed);
46	            if (value < range[0] || value > range[1]) {
47	                throw new InvalidPostcodeException(postcode);
48	            }
49	        }
50	        return trimmed;
51	    }
52	}
