17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "locality", expression = "java(locality(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipLevel",
27	            expression = "java(org.springframework.samples.petclinic.mapper.OwnerMapper.membershipLevel(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
29	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * The owner's derived {@code identityKey} = normalizedTelephone + '|' + (email or empty) + '|' +
34	     * householdId, the single key all duplicate detection is expressed through.
35	     */
36	    default String identityKey(Owner owner) {
37	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(
38	                owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
39	    }
40	
41	    /**
42	     * The owner's preferred contact channel: {@code EMAIL} when an email is present, otherwise
43	     * {@code PHONE}.
44	     */
45	    default String contactPreference(Owner owner) {
46	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
47	    }
48	
49	    default String initials(Owner owner) {
50	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
51	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
52	    }
53	
54	    /** City -> canonical region, from the fixed city-to-region table. */
55	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
56	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
57	
58	    /** Region -> inclusive 4-digit postcode range {low, high}. */
59	    java.util.Map<String, int[]> REGION_RANGE = java.util.Map.of(
60	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
61	
62	    /**
63	     * The owner's locality (region), preferring the postcode: the region whose fixed range contains
64	     * the postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). When the postcode is absent or in
65	     * no known range, falls back to the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
66	     * Brisbane->QLD); {@code UNKNOWN} when neither yields a region.
67	     */
68	    default String locality(Owner owner) {
69	        String fromPostcode = regionFromPostcode(owner.getPostcode());
70	        if (fromPostcode != null) {
71	            return fromPostcode;
72	        }
73	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
74	    }
75	
76	    /** The region whose fixed range contains {@code postcode}, or {@code null} when the postcode is
77	     *  absent, non-numeric, or in no known range. */
78	    private String regionFromPostcode(String postcode) {
79	        if (postcode == null || postcode.isBlank()) {
80	            return null;
81	        }
82	        int value;
83	        try {
84	            value = Integer.parseInt(postcode.trim());
85	        }
86	        catch (NumberFormatException ex) {
87	            return null;
88	        }
89	        for (java.util.Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
90	            int[] range = entry.getValue();
91	            if (value >= range[0] && value <= range[1]) {
92	                return entry.getKey();
93	            }
94	        }
95	        return null;
96	    }
97	
98	    /**
99	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the last two
100	     * digits of the registrationDate year (e.g. {@code SYD-SMI-0007-M26}). Null when either the customer
101	     * code or the registration date is absent.
102	     */
103	    default String membershipNumber(Owner owner) {
104	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
105	            return null;
106	        }
107	        return String.format("%s-M%02d", owner.getCustomerCode(),
108	                owner.getRegistrationDate().getYear() % 100);
109	    }
110	
111	    /**
112	     * The owner's membership level, a number from 1 to 3 assigned on creation. Starts at 1; add 1
113	     * when an email is present; add 1 when the owner's name was unique on creation (namesakeCount is
114	     * 0); capped at 3. Level 4 is reserved for tenure.
115	     */
116	    static int membershipLevel(Owner owner) {
117	        int level = 1;
118	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
119	        if (hasEmail) {
120	            level++;
121	        }
122	        Integer namesakeCount = owner.getNamesakeCount();
123	        if (namesakeCount != null && namesakeCount == 0) {
124	            level++;
125	        }
126	        return Math.min(level, 3);
127	    }
128	
129	    Owner toOwner(OwnerDto ownerDto);
130	
131	    @Mapping(target = "id", ignore = true)
132	    @Mapping(target = "pets", ignore = true)
133	    Owner toOwner(OwnerFieldsDto ownerDto);
134	
135	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
136	
137	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
138	
139	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
140	        OwnerPageDto ownerPageDto = new OwnerPageDto();
141	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
142	        ownerPageDto.setPage(ownerPage.getNumber());
143	        ownerPageDto.setSize(ownerPage.getSize());
144	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
145	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
146	        return ownerPageDto;
147	    }
148	}
