9	public class CityAtCapacityException extends Exception {
10	
11	    /** A city is full once it holds this many owners; the next owner in it is rejected. */
12	    public static final int CAPACITY = 50;
13	
14	    private final String city;
15	
16	    private final int count;
17	
18	    public CityAtCapacityException(String city, int count) {
19	        super("City '" + city + "' already has " + count + " owners (maximum " + CAPACITY + ")");
20	        this.city = city;
21	        this.count = count;
22	    }
23	
24	    public String getCity() {
25	        return this.city;
26	    }
27	
28	    public int getCount() {
29	        return this.count;
30	    }
31	}
