14	/**
15	 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
16	 * firstName, lastName, address, city or telephone. A whitespace-only value counts as blank, which
17	 * bean validation alone does not catch for the pattern-less address/city fields, so the check is
18	 * explicit here. The address is normalized first (see {@link OwnerAddress}) and the required-field
19	 * check rejects an address that is blank after normalization; the normalized value is written back
20	 * so it is stored, returned and used for every later address comparison. The telephone is then
21	 * normalized to E.164 form (see {@link OwnerTelephone}); the
22	 * normalized value is written back so it is stored and returned, and a value that cannot form valid
23	 * E.164 is a 400. The
24	 * optional email, when present, must be a syntactically valid address and is normalized to lower
25	 * case; a present-but-invalid email is a 400. On success it republishes the body for {@link BuildOwner}.
26	 */
27	public class ValidateOwnerFields {
28	
29	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
30	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
31	            InvalidPostcodeException {
32	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
33	        List<String> missing = new ArrayList<>();
34	        require("firstName", request.getFirstName(), missing);
35	        require("lastName", request.getLastName(), missing);
36	        require("address", request.getAddress(), missing);
37	        require("city", request.getCity(), missing);
38	        require("telephone", request.getTelephone(), missing);
39	        if (!missing.isEmpty()) {
40	            throw new MissingOwnerFieldsException(missing);
41	        }
42	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
43	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
44	        request.setPostcode(Postcode.normalize(request.getPostcode(), request.getCity()));
45	        validated.set(request);
46	    }
47	
48	    private static void require(String field, String value, List<String> missing) {
49	        if (value == null || value.isBlank()) {
50	            missing.add(field);
51	        }
52	    }
53	}
